'use strict';
let ptDraft=null,ptStroke=null;
function ptEnsure(){state.treaties??=[];state.titles??={};}
function ptSovereign(key){return state.titles?.[key]||wcLegal(key);}
function ptTruce(a,b){return(state.treaties||[]).find(t=>!t.broken&&!t.superseded&&a!==b&&[t.a,t.b].includes(a)&&[t.a,t.b].includes(b)&&state.turn<t.expiresTurn);}
function ptCountrySize(c){let sum=0;for(let poly of rings(world[c].feature))poly.forEach((r,index)=>{let area=0;for(let i=0,j=r.length-1;i<r.length;j=i++)area+=r[j][0]*r[i][1]-r[i][0]*r[j][1];sum+=(index?-1:1)*Math.abs(area/2);});return Math.max(1,sum/(WC_WIDTH*WC_HEIGHT));}
let ptBorderCache=new Map(),ptBorderState=null,ptBorderRevision=-1;
function ptHexEdge(key,index){let [q,r]=key.split(',').map(Number);return WC_EDGES[index].map(c=>{let [x,y]=WC_CORNERS[c];return(2*q+r+x)+','+(3*r+y);});}
function ptEdgeId(a,b){return a<b?a+'|'+b:b+'|'+a;}
function ptCountryLoops(c){
 if(!state)return wcCountryLoops(c);
 let revision=state.titleRevision||0;if(ptBorderState!==state||ptBorderRevision!==revision){ptBorderCache=new Map();ptBorderState=state;ptBorderRevision=revision;}
 if(ptBorderCache.has(c))return ptBorderCache.get(c);
 let changed=Object.keys(state.titles).filter(k=>state.titles[k]!==wcLegal(k)&&(state.titles[k]===c||wcLegal(k)===c));
 if(!changed.length){let original=wcCountryLoops(c);ptBorderCache.set(c,original);return original;}
 let edges=new Map(),affected=new Set();
 for(let loop of wcCountryLoops(c))for(let i=0;i<loop.length;i++){let p=loop[i],n=loop[(i+1)%loop.length],a=Math.round(p[0]/(WC_WIDTH/2))+','+Math.round(p[1]/(WC_RADIUS/2)),b=Math.round(n[0]/(WC_WIDTH/2))+','+Math.round(n[1]/(WC_RADIUS/2));edges.set(ptEdgeId(a,b),[a,b]);}
 for(let k of changed){affected.add(k);for(let n of wcNeighbors(k))affected.add(n);}
 // Remove obsolete edges before adding new ones, so the former border disappears.
 for(let k of affected)for(let i=0;i<6;i++){let [a,b]=ptHexEdge(k,i);edges.delete(ptEdgeId(a,b));}
 for(let k of affected){let own=ptSovereign(k)===c,neighbors=wcNeighbors(k);for(let i=0;i<6;i++){let neighborOwn=ptSovereign(neighbors[i])===c;if(own===neighborOwn)continue;let [a,b]=ptHexEdge(k,i);edges.set(ptEdgeId(a,b),own?[a,b]:[b,a]);}}
 let next=new Map([...edges.values()]),loops=[];
 while(next.size){let start=next.keys().next().value,current=start,loop=[];do{let [x,y]=current.split(',').map(Number);loop.push([x*WC_WIDTH/2,y*WC_RADIUS/2]);let destination=next.get(current);next.delete(current);current=destination;}while(current&&current!==start);if(current!==start)throw Error('Treaty border did not close for '+c);if(loop.length>=3)loops.push(loop);}
 ptBorderCache.set(c,loops);return loops;
}
function ptCountryLabelPoint(c){let original=world[c].center;if(!state||ptSovereign(wcKey(...original))===c)return original;for(let loop of [...ptCountryLoops(c)].sort((a,b)=>b.length-a.length))for(let i=0;i<loop.length;i+=Math.max(1,Math.floor(loop.length/30))){let key=wcKey(...loop[i]);for(let candidate of [key,...wcNeighbors(key)])if(ptSovereign(candidate)===c)return wcPoint(candidate);}return null;}
function ptCountryPath(c){ctx.beginPath();for(let loop of ptCountryLoops(c)){loop.forEach((p,i)=>{let q=screen(...p);i?ctx.lineTo(...q):ctx.moveTo(...q);});ctx.closePath();}}
function ptInvalidateBorders(){state.titleRevision=(state.titleRevision||0)+1;ptBorderCache=new Map();}
function ptSubjectCycle(subject,overlord){let seen=new Set([subject]);for(let c=overlord;c;c=state.countries[c]?.overlord){if(seen.has(c))return true;seen.add(c);}return false;}
function ptOpen(){let war=wcFind(state.player,target,true);if(!war||war.active){notify('Agree a ceasefire before negotiating peace terms.');return;}ptEnsure();$('#hover').style.display='none';clearInterval(timer);timer=null;ptDraft={war:war.id,other:target,claims:{},count:0,brush:'demand',radius:1,years:5,reparations:0,paymentYears:5,vassal:state.countries[target].overlord===state.player,message:''};let p=center(target);view={x:p[0],y:p[1],z:8};render();}
function ptClose(){ptDraft=null;ptStroke=null;render();}
function ptPaintKey(key,mode){if(!ptDraft)return;ptDraft.count??=Object.keys(ptDraft.claims).length;let c=ptSovereign(key);if(![state.player,ptDraft.other].includes(c))return;if(mode==='erase'){if(key in ptDraft.claims){delete ptDraft.claims[key];ptDraft.count--;}return;}let recipient=mode==='offer'?ptDraft.other:state.player;if(recipient===c){if(key in ptDraft.claims){delete ptDraft.claims[key];ptDraft.count--;}return;}if(ptDraft.count>=20000&&!(key in ptDraft.claims)){ptDraft.message='A proposal can contain up to 20,000 sectors.';return;}if(!(key in ptDraft.claims))ptDraft.count++;ptDraft.claims[key]=recipient;}
function ptPaint(x,y,from){let key=wcKey(...geo(x,y)),points=[key];if(from){let [q0,r0]=from.split(',').map(Number),[q1,r1]=key.split(',').map(Number),n=Math.max(Math.abs(q1-q0),Math.abs(r1-r0),Math.abs(q1+r1-q0-r0));for(let i=0;i<=n;i++)points.push(Math.round(q0+(q1-q0)*i/Math.max(1,n))+','+Math.round(r0+(r1-r0)*i/Math.max(1,n)));}ptDraft.message='';for(let k of points){let [q,r]=k.split(',').map(Number),radius=ptDraft.radius;for(let dq=-radius;dq<=radius;dq++)for(let dr=Math.max(-radius,-dq-radius);dr<=Math.min(radius,-dq+radius);dr++)ptPaintKey((q+dq)+','+(r+dr),ptDraft.brush);}ptUpdateSummary();draw();return key;}
function ptSelectOccupied(){if(!ptDraft)return;let keys=new Set(Object.keys(state.control));if(state.mode==='control')for(let k of wcScenarioGrid().keys)keys.add(k);for(let k of keys)if(ptSovereign(k)===ptDraft.other&&wcOwner(k)===state.player)ptPaintKey(k,'demand');ptUpdateSummary();draw();}
function ptTerms(){let d=ptDraft;if(!d)throw Error('No peace draft');let years=Number(d.years),paymentYears=Number(d.paymentYears),reparations=Number(d.reparations);if(!Number.isInteger(years)||years<1||years>50)throw Error('Truce length must be a whole number from 1 to 50 years.');if(!Number.isInteger(paymentYears)||paymentYears<1||paymentYears>20)throw Error('Payment period must be 1–20 years.');if(!Number.isFinite(reparations)||reparations< -30||reparations>30)throw Error('Reparations must be between -30% and 30% of the payer GDP.');let war=state.wars.find(w=>w.id===d.war);if(!war||war.active||![war.a,war.b].includes(state.player)||![war.a,war.b].includes(d.other))throw Error('These governments must remain at ceasefire.');let claims=Object.entries(d.claims);if(claims.length>20000)throw Error('Too many selected sectors.');for(let [key,to] of claims)if(![state.player,d.other].includes(ptSovereign(key))||![state.player,d.other].includes(to)||ptSovereign(key)===to)throw Error('One of the selected sectors is no longer eligible.');if(d.vassal&&ptSubjectCycle(d.other,state.player))throw Error('Vassalization would create a circular dependency.');return{war,years,paymentYears,reparations,claims,other:d.other,vassal:!!d.vassal};}
function ptAcceptance(terms){let {war,claims,other,years,reparations,vassal}=terms,ours=state.player,demand=claims.filter(([,to])=>to===ours),offer=claims.filter(([,to])=>to===other),held=demand.filter(([k])=>wcOwner(k)===ours).length;let leverage=clamp(Math.log((wcPower(war,ours)+1)/(wcPower(war,other)+1))*15,-25,30),score=57+war.fatigue[other]*.28+leverage+Math.min(6,years/5);score-=Math.min(95,demand.length/ptCountrySize(other)*160);score-=Math.min(35,(demand.length-held)/ptCountrySize(other)*140);score+=Math.min(35,offer.length/ptCountrySize(ours)*160);score-=Math.max(0,reparations)*1.4;score+=Math.max(0,-reparations)*1.1;if(vassal&&state.countries[other].overlord!==ours)score-=48;if(!vassal&&state.countries[other].overlord===ours)score+=15;for(let city of wcCities())if(city.capital&&city.home===other&&demand.some(([k])=>k===city.key)){score-=22;if(wcCityOwner(city)===ours)score+=22;}if(state.countries[other].morale<35)score+=18;return clamp(score,0,100);}
function ptSummary(){if(!ptDraft)return'';try{let t=ptTerms(),d=t.claims.filter(([,to])=>to===state.player).length;return d+' demanded · '+(t.claims.length-d)+' offered sectors. '+(ptAcceptance(t)>=50?'Likely to accept':'Likely to reject')+' under current conditions.';}catch(e){return e.message;}}
function ptUpdateSummary(){let e=$('#treatySummary');if(e)e.textContent=ptSummary();let m=$('#treatyMessage');if(m)m.textContent=ptDraft?.message||'';}
function ptPanel(){let d=ptDraft;if(!d)return;$('#map').style.cursor=d.brush==='pan'?'grab':'crosshair';let html='<div class="eyebrow">PEACE CONFERENCE</div><h2 class="targetTitle">'+name(d.other)+'</h2><p class="note">Paint hexes on the map. Gold = your demands; blue = concessions. Zoom in for single sectors. Select Pan to move the map.</p><div class="treatyTools">';for(let [tool,label] of [['demand','Demand'],['offer','Offer'],['erase','Erase'],['pan','Pan']])html+='<button data-treaty-tool="'+tool+'" class="'+(d.brush===tool?'primary':'')+'">'+label+'</button>';html+='</div><label class="row">Brush size<select id="treatyRadius" aria-label="Treaty brush size">';for(let r of [0,1,2,3])html+='<option value="'+r+'" '+(r===d.radius?'selected':'')+'>'+(r===0?'Single hex':r+' rings')+'</option>';html+='</select></label><button class="wide" id="treatyOccupied">Select occupied opponent sectors</button><button class="wide" id="treatyClear">Clear selected hexes</button><label class="row">Truce, years<input id="treatyYears" aria-label="Truce years" type="number" min="1" max="50" step="1" value="'+d.years+'"></label><label class="row">Reparations, % GDP<input id="treatyReparations" aria-label="Reparations percentage" type="number" min="-30" max="30" step="1" value="'+d.reparations+'"></label><p class="note">Positive: they pay you. Negative: you pay them. Total uses payer GDP at signing. Earlier unpaid reparations remain due; this amount is additional.</p><label class="row">Payment period, years<input id="treatyPaymentYears" aria-label="Reparations payment years" type="number" min="1" max="20" step="1" value="'+d.paymentYears+'"></label><label class="row"><span>Vassal under your government</span><input id="treatyVassal" type="checkbox" '+(d.vassal?'checked':'')+'></label><p class="note">Vassals pay 1% of annual GDP in monthly tribute and receive defensive ties. Independent declarations of war are restricted.</p><div class="card"><p id="treatySummary">'+ptSummary()+'</p><p id="treatyMessage" role="status">'+d.message+'</p></div><button id="treatyPropose" class="wide primary">Propose peace treaty</button><button id="treatyCancel" class="wide">Return to diplomacy</button>';$('#target').innerHTML=html;}
function ptSign(){let t;try{t=ptTerms();}catch(e){ptDraft.message=e.message;ptUpdateSummary();return false;}if(ptAcceptance(t)<50){ptDraft.message='Proposal rejected: reduce demands, offer concessions, or improve your leverage.';ptUpdateSummary();return false;}ptEnsure();let ours=state.player,other=t.other;for(let [key,to] of t.claims){state.titles[key]=to;wcSetOwner(key,to,t.war);}if(t.claims.length)ptInvalidateBorders();let payer=t.reparations>=0?other:ours,payee=payer===other?ours:other,total=state.countries[payer].gdp*Math.abs(t.reparations)/100;for(let old of state.treaties)if(!old.broken&&[old.a,old.b].includes(ours)&&[old.a,old.b].includes(other))old.superseded=true;let record={id:'treaty_'+ours+'_'+other+'_'+state.turn,a:ours,b:other,signedTurn:state.turn,expiresTurn:state.turn+t.years*12,truceYears:t.years,claims:t.claims,vassal:t.vassal,broken:false,reparations:{payer,payee,total,remaining:total,monthsLeft:t.paymentYears*12,monthly:total/(t.paymentYears*12)}};state.treaties.push(record);if(t.vassal){state.countries[other].overlord=ours;for(let [a,b] of [[ours,other],[other,ours]])if(!state.countries[a].allies.includes(b))state.countries[a].allies.push(b);}else if(state.countries[other].overlord===ours)delete state.countries[other].overlord;t.war.treaty=record.id;simSetRelation(ours,other,Math.max(-25,simRelation(ours,other)+20));log('Peace treaty signed with '+name(other)+': '+t.claims.length+' sectors settled, '+t.years+'-year truce'+(total?', '+money(total)+' reparations':'')+(t.vassal?', vassalization':'')+'.',true);ptDraft=null;ptStroke=null;render();save(false);notify('Treaty signed. Territory transfers and the truce are in effect.');return true;}
function ptBreak(record,breaker){record.broken=true;record.brokenTurn=state.turn;record.breaker=breaker;for(let prior of state.treaties)if([prior.a,prior.b].includes(record.a)&&[prior.a,prior.b].includes(record.b)&&prior.reparations)prior.reparations.remaining=0;let victims=[record.a,record.b].filter(c=>c!==breaker),sanctioners=[];if(breaker===state.player){state.legitimacy=clamp(state.legitimacy-15,0,100);state.approval=clamp(state.approval-8,0,100);}else state.countries[breaker].ai.approval=clamp(state.countries[breaker].ai.approval-8,0,100);for(let c in state.countries){if(c===breaker)continue;let before=simRelation(c,breaker);simSetRelation(c,breaker,before-(victims.includes(c)?40:12));if(victims.includes(c)||state.countries[c].owner!==c||state.countries[c].overlord===breaker)continue;let risk=allied(c,breaker)?.08:before<0?.65:.35;if(simRandom()<risk){if(!state.countries[c].sanctions.includes(breaker))state.countries[c].sanctions.push(breaker);state.countries[c].trades=state.countries[c].trades.filter(x=>x!==breaker);state.countries[breaker].trades=state.countries[breaker].trades.filter(x=>x!==c);sanctioners.push(c);}}log(name(breaker)+' broke a binding truce. '+(sanctioners.length?sanctioners.map(name).slice(0,6).join(', ')+(sanctioners.length>6?' and others':'')+' imposed sanctions.':'Relations deteriorated, but no new sanctions were imposed.'),true);return sanctioners;}
function ptBeforeWar(a,b){ptEnsure();let overlord=state.countries[a].overlord;if(overlord&&overlord!==b){notify('Your vassal obligations restrict independent declarations of war.');return false;}state.countries[a].trades=state.countries[a].trades.filter(c=>c!==b);state.countries[b].trades=state.countries[b].trades.filter(c=>c!==a);if(state.countries[b].overlord===a){delete state.countries[b].overlord;state.countries[a].allies=state.countries[a].allies.filter(c=>c!==b);state.countries[b].allies=state.countries[b].allies.filter(c=>c!==a);}let truce=ptTruce(a,b);if(truce)ptBreak(truce,a);if(overlord===b){delete state.countries[a].overlord;state.countries[a].allies=state.countries[a].allies.filter(c=>c!==b);state.countries[b].allies=state.countries[b].allies.filter(c=>c!==a);log(name(a)+' rebelled against '+name(b)+'.',true);}return true;}
function ptMonthly(){ptEnsure();for(let t of state.treaties){if(!t.broken&&!t.superseded&&state.turn===t.expiresTurn)log('The '+t.truceYears+'-year truce between '+name(t.a)+' and '+name(t.b)+' has expired.');let p=t.reparations;if(t.broken||!p||p.remaining<=0||p.monthsLeft<=0)continue;let payer=state.countries[p.payer],recipient=state.countries[p.payee],due=Math.min(p.remaining,p.monthly),paid=Math.min(due,payer.treasury);payer.treasury-=paid;recipient.treasury+=paid;p.remaining=Math.max(0,p.remaining-paid);if(paid>=due-1e-8)p.monthsLeft--;else if(state.turn%12===0)log(name(p.payer)+' has fallen behind on treaty reparations.');}for(let c in state.countries){let n=state.countries[c],overlord=state.countries[n.overlord];if(!overlord)continue;let due=Math.min(n.treasury,n.gdp*.01/12);n.treasury-=due;overlord.treasury+=due;}}
function ptSanctions(c){return Object.values(state.countries).filter(n=>n.code!==c&&n.sanctions.includes(c)).length;}
function ptDiplomacyButton(c){let w=wcFind(state.player,c),past=wcFind(state.player,c,true),truce=ptTruce(state.player,c);if(w)return actionButton('peace','Negotiate ceasefire');return(past?actionButton('treaty',truce?'Renegotiate peace treaty':'Negotiate peace treaty'):'')+actionButton('war',truce?'Break truce & declare war':past?'Resume hostilities':'Declare war','danger');}
function ptStatus(c){let truce=ptTruce(state.player,c),n=state.countries[c],html='';if(truce)html+='<div class="card"><b>Binding truce</b><p>'+((truce.expiresTurn-state.turn)/12).toFixed(1)+' years remaining. Breaking it costs legitimacy and approval, damages relations, and risks sanctions.</p></div>';if(truce?.reparations?.remaining>0)html+='<p class="note">Reparations remaining: '+money(truce.reparations.remaining)+' · '+(truce.reparations.payer===state.player?'you pay':'you receive')+' up to '+money(truce.reparations.monthly)+' monthly.</p>';if(n.overlord)html+='<span class="tag">Vassal of '+name(n.overlord)+'</span>';let sanctions=ptSanctions(c);if(sanctions)html+='<p class="note">Sanctioned by '+sanctions+' governments · growth and trade affected.</p>';return html;}
function ptDraw(){if(!ptDraft)return;ctx.save();for(let [key,to] of Object.entries(ptDraft.claims)){let p=screen(...wcPoint(key));if(p[0]<-10||p[0]>W+10||p[1]<-10||p[1]>H+10)continue;ctx.fillStyle=to===state.player?'#f4d77bb8':'#70c9ffb8';ctx.beginPath();wcHexPath(key);ctx.fill();}ctx.restore();}
function ptDrawTitles(){if(!state.titles)return;let countries=new Set();for(let key in state.titles)if(state.titles[key]!==wcLegal(key)){countries.add(wcLegal(key));countries.add(state.titles[key]);}ctx.strokeStyle='#172c31';ctx.lineWidth=.8;for(let c of countries)if(c){ptCountryPath(c);ctx.stroke();}}

function ptCashflow(c){let net=0;for(let t of state.treaties||[]){let p=t.reparations;if(t.broken||!p||p.remaining<=0)continue;let amount=Math.min(p.remaining,p.monthly);if(p.payer===c)net-=amount;if(p.payee===c)net+=amount;}let n=state.countries[c];if(n.overlord)net-=n.gdp*.01/12;for(let subject of Object.values(state.countries))if(subject.overlord===c)net+=subject.gdp*.01/12;return net;}
document.addEventListener('click',e=>{let tool=e.target.closest('[data-treaty-tool]');if(tool&&ptDraft){ptDraft.brush=tool.dataset.treatyTool;ptPanel();return;}let id=e.target.closest('button')?.id;if(id==='treatyOccupied')ptSelectOccupied();if(id==='treatyClear'&&ptDraft){ptDraft.claims={};ptDraft.count=0;ptUpdateSummary();draw();}if(id==='treatyPropose')ptSign();if(id==='treatyCancel')ptClose();});
document.addEventListener('input',e=>{if(!ptDraft)return;let fields={treatyYears:'years',treatyPaymentYears:'paymentYears',treatyReparations:'reparations',treatyRadius:'radius',treatyVassal:'vassal'},key=fields[e.target.id];if(key){ptDraft[key]=e.target.id==='treatyVassal'?e.target.checked:Number(e.target.value);ptDraft.message='';ptUpdateSummary();}});
const ptCanvas=document.querySelector('#map');
ptCanvas.addEventListener('pointerdown',e=>{if(!ptDraft||ptDraft.brush==='pan'||e.button>0)return;e.preventDefault();e.stopImmediatePropagation();ptCanvas.setPointerCapture(e.pointerId);ptStroke={id:e.pointerId,last:ptPaint(e.offsetX,e.offsetY)};},true);
ptCanvas.addEventListener('pointermove',e=>{if(!ptDraft||ptDraft.brush==='pan')return;e.stopImmediatePropagation();if(ptStroke?.id===e.pointerId){e.preventDefault();ptStroke.last=ptPaint(e.offsetX,e.offsetY,ptStroke.last);}},true);
ptCanvas.addEventListener('pointerup',e=>{if(!ptDraft||ptDraft.brush==='pan')return;e.preventDefault();e.stopImmediatePropagation();ptStroke=null;},true);
ptCanvas.addEventListener('pointercancel',()=>{ptStroke=null;},true);
